 4→import static org.junit.jupiter.api.Assertions.*;
 5→
 6→class Float16Test {
 7→
 8→    private static final float HALF_EPSILON = 0.001f; // tolerance for float16 precision
 9→
10→    @Test
11→    void roundTrip_positiveFloat() {
12→        float original = 3.14f;
13→        short bits = Float16.fromFloat(original);
14→        float recovered = Float16.toFloat(bits);
15→        assertEquals(original, recovered, HALF_EPSILON, "positive float roundtrip");
16→    }
17→
18→    @Test
19→    void roundTrip_negativeFloat() {
20→        float original = -2.5f;
21→        short bits = Float16.fromFloat(original);
22→        float recovered = Float16.toFloat(bits);
23→        assertEquals(original, recovered, HALF_EPSILON, "negative float roundtrip");
24→    }
25→
26→    @Test
27→    void roundTrip_zero() {
28→        assertEquals(0.0f, Float16.toFloat(Float16.fromFloat(0.0f)), 0.0f);
29→    }
30→
31→    @Test
32→    void roundTrip_positiveInfinity() {
33→        assertEquals(Float.POSITIVE_INFINITY,
34→                Float16.toFloat(Float16.fromFloat(Float.POSITIVE_INFINITY)));
35→    }
36→
37→    @Test
38→    void roundTrip_negativeInfinity() {
39→        assertEquals(Float.NEGATIVE_INFINITY,
40→                Float16.toFloat(Float16.fromFloat(Float.NEGATIVE_INFINITY)));
41→    }
42→
43→    @Test
44→    void roundTrip_nan() {
45→        assertTrue(Float.isNaN(Float16.toFloat(Float16.fromFloat(Float.NaN))));
46→    }
47→
48→    @Test
49→    void fromFloat_minSubnormal() {
50→        // Minimum positive subnormal half-precision value ~ 5.96e-8
51→        short minSubnormal = (short) 0x0001;
52→        float val = Float16.toFloat(minSubnormal);
53→        assertTrue(val > 0.0f && val < 1e-6f, "min subnormal should be very small positive");
54→        // Round-trip from that value should give same bits
55→        short recovered = Float16.fromFloat(val);
56→        assertEquals(minSubnormal, recovered, "min subnormal round trip bits");
57→    }
58→}
