    final Object[] subValues = sub.values();
    final int boolCount = countBoolFields(subFields);
    final int nullMaskBytes = (subFields.size() + 7) / 8;
    final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;

